import React, { useState, useEffect } from "react";
import {
  Paper,
  Typography,
  TextField,
  Button,
  Box,
  Alert,
  CircularProgress,
  Stack,
  Link,
  Divider,
  InputAdornment,
  IconButton,
  FormControlLabel,
  Checkbox,
  Card,
  CardContent,
  ToggleButton,
  ToggleButtonGroup,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
} from "@mui/material";
import {
  Visibility,
  VisibilityOff,
  PersonAddOutlined,
  LockOutlined,
  EmailOutlined,
  PersonOutline,
} from "@mui/icons-material";
import { useNavigate, Link as RouterLink, useSearchParams } from "react-router-dom";
import { alpha, useTheme } from "@mui/material/styles";
import ApiService from "../services/api";
import { useRegistration } from "../context/RegistrationContext";
import FormErrorSummary from "./shared/FormErrorSummary";
import BrandLogoMark from "./BrandLogoMark";
import {
  SIGNUP_GOAL_OPTIONS,
  SignupGoalId,
  setStoredSignupGoal,
} from "../constants/signupGoals";
import {
  billingPathForPlanIntent,
  clearPendingBillingPlanId,
  getPendingBillingPlanId,
  setPendingBillingPlanId,
} from "../utils/billingPlanIntent";
import { SUBSCRIPTION_PLANS_ENABLED } from "../constants/subscriptionPlans";
import { resolveMsmePostLoginDestination } from "../utils/resolvePostLoginDestination";
import { PARTNER_ORGANIZATION_TYPES, PartnerOrganizationType } from "../constants/partnerProgram";
import PartnerOnboardingWizard from "./partner/PartnerOnboardingWizard";
import axios from "axios";
import { buildApiUrl } from "../config/apiConfig";

type RegisterAccountType = "msme" | "partner";

// Match your User model fields
type RegisterFormData = {
  email: string;
  password: string;
  confirmPassword: string;
  // role: string;
  firstName: string;
  lastName: string;
  phone: string;
  agreeToTerms: boolean;
  organizationName: string;
  organizationType: PartnerOrganizationType;
};

// Define error type
type FormErrors = {
  email?: string;
  password?: string;
  confirmPassword?: string;
  // role?: string;
  firstName?: string;
  lastName?: string;
  phone?: string;
  agreeToTerms?: string;
  organizationName?: string;
  organizationType?: string;
};

const UserRegister: React.FC = () => {
  const theme = useTheme();
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { isRegistered, login, setAccountPathway } = useRegistration();
  const selectedPlanId = searchParams.get("plan")?.trim() || null;
  const initialAccountType: RegisterAccountType =
    searchParams.get("type")?.trim() === "partner" ? "partner" : "msme";
  const [accountType, setAccountType] = useState<RegisterAccountType>(initialAccountType);
  const [isRegistering, setIsRegistering] = useState(false);
  const [registerError, setRegisterError] = useState<string | null>(null);
  const [registerSuccess, setRegisterSuccess] = useState<string | null>(null);
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  // Form state - match your User model
  const [formData, setFormData] = useState<RegisterFormData>({
    email: "",
    password: "",
    confirmPassword: "",
    // role: "msme", // Default as per your schema
    firstName: "",
    lastName: "",
    phone: "",
    agreeToTerms: false,
    organizationName: "",
    organizationType: "integration_partner",
  });

  // Validation state
  const [errors, setErrors] = useState<FormErrors>({});
  const [signupGoal, setSignupGoal] = useState<SignupGoalId | null>(null);
  const [partnerWizardOpen, setPartnerWizardOpen] = useState(false);
  const [partnerApiKeyFull, setPartnerApiKeyFull] = useState<string | null>(null);

  // Redirect if already logged in
  useEffect(() => {
    if (isRegistered) {
      navigate("/dashboard");
    }
  }, [isRegistered, navigate]);

  useEffect(() => {
    const typeParam = searchParams.get("type")?.trim();
    if (typeParam === "partner") {
      setAccountType("partner");
    } else if (typeParam === "msme") {
      setAccountType("msme");
    }
  }, [searchParams]);

  useEffect(() => {
    if (selectedPlanId) {
      setPendingBillingPlanId(selectedPlanId);
    }
  }, [selectedPlanId]);

  // Handle input changes
  const handleInputChange = (field: keyof RegisterFormData, value: any) => {
    setFormData(prev => ({
      ...prev,
      [field]: value
    }));
    
    // Clear error when user starts typing
    if (errors[field]) {
      setErrors(prev => ({
        ...prev,
        [field]: undefined
      }));
    }
  };

  // Validation function - match your User model requirements
  const validateForm = (): boolean => {
    const newErrors: FormErrors = {};

    // Email validation
    if (!formData.email.trim()) {
      newErrors.email = "Email is required";
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = "Invalid email format";
    }

    // Password validation - minlength: 6 as per schema
    if (!formData.password) {
      newErrors.password = "Password is required";
    } else if (formData.password.length < 6) {
      newErrors.password = "Password must be at least 6 characters";
    }

    // Confirm Password validation
    if (!formData.confirmPassword) {
      newErrors.confirmPassword = "Confirm password is required";
    } else if (formData.confirmPassword !== formData.password) {
      newErrors.confirmPassword = "Passwords must match";
    }

    // Role validation - enum: ['admin', 'view', 'msme']
    // if (!formData.role) {
    //   newErrors.role = "Role is required";
    // } else if (!["admin", "view", "msme"].includes(formData.role)) {
    //   newErrors.role = "Invalid role";
    // }

    // First Name validation
    if (!formData.firstName.trim()) {
      newErrors.firstName = "First name is required";
    }

    // Last Name validation
    if (!formData.lastName.trim()) {
      newErrors.lastName = "Last name is required";
    }

    // Phone validation (optional in schema, but you can make it required in form)
    if (!formData.phone.trim()) {
      newErrors.phone = "Phone number is required";
    }

    // Terms validation
    if (!formData.agreeToTerms) {
      newErrors.agreeToTerms = "You must agree to the terms and conditions";
    }

    if (accountType === "partner") {
      if (!formData.organizationName.trim()) {
        newErrors.organizationName = "Organization name is required";
      }
      if (!formData.organizationType) {
        newErrors.organizationType = "Organization type is required";
      }
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const completeRegistration = async () => {
    setIsRegistering(true);
    const registeredEmail = formData.email;
    const registeredPassword = formData.password;
    try {
      const payload =
        accountType === "partner"
          ? {
              email: formData.email,
              password: formData.password,
              role: "partner",
              profile: {
                firstName: formData.firstName,
                lastName: formData.lastName,
                phone: formData.phone,
              },
              partnerProfile: {
                organizationName: formData.organizationName,
                organizationType: formData.organizationType,
              },
            }
          : {
              email: formData.email,
              password: formData.password,
              role: "msme",
              profile: {
                firstName: formData.firstName,
                lastName: formData.lastName,
                phone: formData.phone,
              },
            };

      const response = await ApiService.register(payload);

      if (!response?.success) {
        throw new Error(
          response?.message || "Registration failed. Please try again.",
        );
      }

      let shouldRedirectToLogin = false;

      if (accountType === "partner") {
        const apiKey = (response?.data?.partner as { apiKeyFull?: string })?.apiKeyFull;
        const token = (response?.data as { token?: string })?.token;
        if (token) {
          localStorage.setItem("token", token);
        }
        if (apiKey) {
          setPartnerApiKeyFull(apiKey);
          setPartnerWizardOpen(true);
          setRegisterSuccess(null);
          setIsRegistering(false);
          return;
        }
        setRegisterSuccess(
          "Partner account created! You can now sign in to access your partner portal.",
        );
        shouldRedirectToLogin = true;
      } else {
        setAccountPathway("msme");
        try {
          const redirectPath = await login(registeredEmail, registeredPassword, "msme");
          if (redirectPath) {
            navigate(redirectPath);
            return;
          }
          const destination = await resolveMsmePostLoginDestination();
          const pendingPlanId = getPendingBillingPlanId();
          if (pendingPlanId && destination === "/dashboard") {
            clearPendingBillingPlanId();
            navigate(billingPathForPlanIntent(pendingPlanId));
            return;
          }
          navigate(destination);
          return;
        } catch {
          setRegisterSuccess(
            "Account created. Sign in with your email and password to continue.",
          );
          shouldRedirectToLogin = true;
        }
      }
      setFormData({
        email: "",
        password: "",
        confirmPassword: "",
        firstName: "",
        lastName: "",
        phone: "",
        agreeToTerms: false,
        organizationName: "",
        organizationType: "integration_partner",
      });

      if (shouldRedirectToLogin) {
        const planQuery =
          accountType === "msme" && selectedPlanId
            ? `&plan=${encodeURIComponent(selectedPlanId)}`
            : "";
        const loginPath =
          accountType === "partner" ? "/login?type=partner" : `/login?type=msme${planQuery}`;
        setTimeout(() => {
          navigate(loginPath);
        }, 2000);
      }
    } catch (error) {
      setRegisterError(error instanceof Error ? error.message : "Registration failed. Please try again.");
    } finally {
      setIsRegistering(false);
    }
  };

  const handleTogglePasswordVisibility = () => {
    setShowPassword((prev) => !prev);
  };

  const handleToggleConfirmPasswordVisibility = () => {
    setShowConfirmPassword((prev) => !prev);
  };

  const submitButtonLabel = isRegistering
    ? accountType === "partner"
      ? "Creating partner account..."
      : "Creating Account..."
    : accountType === "partner"
      ? "Register as partner"
      : "Create Account";
  const submitButtonIcon = <PersonAddOutlined />;

  const handleRegistrationSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setRegisterError(null);
    setRegisterSuccess(null);

    if (!validateForm()) {
      return;
    }

    await completeRegistration();
  };

  const isDark = theme.palette.mode === "dark";

  return (
    <Box
      sx={{
        minHeight: "100vh",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        py: 4,
        px: 2,
        ...(isDark
          ? {
              backgroundColor: theme.palette.background.default,
              backgroundImage: `radial-gradient(ellipse 120% 80% at 0% -20%, ${alpha(theme.palette.primary.main, 0.16)} 0%, transparent 55%), radial-gradient(ellipse 100% 60% at 100% 0%, ${alpha(theme.palette.secondary.main, 0.08)} 0%, transparent 50%)`,
            }
          : {
              background: "linear-gradient(135deg, #e8f5e9 0%, #c8e6c9 100%)",
            }),
      }}
    >
      <Paper
        elevation={3}
        sx={{
          maxWidth: 600,
          width: "100%",
          p: { xs: 3, sm: 5 },
          borderRadius: 3,
          background:
            theme.palette.mode === "light"
              ? "linear-gradient(135deg, #ffffff 0%, #f8fafc 100%)"
              : `linear-gradient(160deg, ${theme.palette.background.paper} 0%, ${alpha(theme.palette.common.white, 0.04)} 100%)`,
          border: `1px solid ${alpha(theme.palette.primary.main, isDark ? 0.28 : 0.12)}`,
        }}
      >
        {/* Header Section */}
        <Box sx={{ textAlign: "center", mb: 4 }}>
          <BrandLogoMark width={260} sx={{ mb: 2 }} />
          <Typography
            variant="h4"
            component="h1"
            gutterBottom
            sx={{
              fontWeight: 700,
              background: "linear-gradient(135deg, #4caf50 0%, #2e7d32 100%)",
              backgroundClip: "text",
              WebkitBackgroundClip: "text",
              WebkitTextFillColor: "transparent",
            }}
          >
            Create Account
          </Typography>
          <Typography variant="body1" color="text.secondary">
            {accountType === "partner"
              ? "Register your organization as a Carbon Intelligence partner"
              : "Join Carbon Intelligence Platform"}
          </Typography>
        </Box>

        <Box sx={{ display: "flex", justifyContent: "center", mb: 3 }}>
          <ToggleButtonGroup
            exclusive
            value={accountType}
            onChange={(_, value: RegisterAccountType | null) => {
              if (value) {
                setAccountType(value);
                setRegisterError(null);
              }
            }}
            size="small"
            aria-label="Account type"
          >
            <ToggleButton value="msme">MSME company</ToggleButton>
            <ToggleButton value="partner">Partner organization</ToggleButton>
          </ToggleButtonGroup>
        </Box>

        {/* Success Alert */}
        {registerSuccess && (
          <Alert severity="success" sx={{ mb: 3 }}>
            {registerSuccess}
          </Alert>
        )}

        {selectedPlanId && accountType === "msme" && !registerSuccess && (
          <Alert severity="info" sx={{ mb: 3 }}>
            Your selected plan will be pre-selected in Billing after your MSME profile is created.
          </Alert>
        )}

        {accountType === "partner" && !registerSuccess && (
          <Alert severity="info" sx={{ mb: 3 }}>
            Partner registration creates your portal account and a linked partner application with scoped API
            access. Sign in after registration to open your partner dashboard.
          </Alert>
        )}

        {/* Error Alert */}
        {registerError && (
          <Alert severity="error" sx={{ mb: 3 }}>
            {registerError}
          </Alert>
        )}

        <FormErrorSummary messages={Object.values(errors).filter(Boolean) as string[]} />

        {/* Registration Form */}
        <form onSubmit={handleRegistrationSubmit}>
          <Stack spacing={3}>
            <Card variant="outlined" sx={{ bgcolor: "action.hover", display: accountType === "msme" ? "block" : "none" }}>
              <CardContent>
                <Typography variant="subtitle2" sx={{ fontWeight: 700, mb: 0.5 }}>
                  What do you need first?
                </Typography>
                <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
                  We tailor onboarding steps and compliance focus to your goal.
                </Typography>
                <Stack spacing={1}>
                  {SIGNUP_GOAL_OPTIONS.map((opt) => (
                    <FormControlLabel
                      key={opt.id}
                      control={
                        <Checkbox
                          checked={signupGoal === opt.id}
                          onChange={() => {
                            const next = signupGoal === opt.id ? null : opt.id;
                            setSignupGoal(next);
                            setStoredSignupGoal(next);
                          }}
                        />
                      }
                      label={
                        <Box>
                          <Typography variant="body2" sx={{ fontWeight: 600 }}>
                            {opt.label}
                          </Typography>
                          <Typography variant="caption" color="text.secondary">
                            {opt.description}
                          </Typography>
                        </Box>
                      }
                    />
                  ))}
                </Stack>
              </CardContent>
            </Card>

            {accountType === "partner" && (
              <>
                <TextField
                  fullWidth
                  label="Organization name"
                  value={formData.organizationName}
                  onChange={(e) => handleInputChange("organizationName", e.target.value)}
                  error={!!errors.organizationName}
                  helperText={errors.organizationName}
                />
                <FormControl fullWidth error={!!errors.organizationType}>
                  <InputLabel>Organization type</InputLabel>
                  <Select
                    value={formData.organizationType}
                    label="Organization type"
                    onChange={(e) =>
                      handleInputChange("organizationType", e.target.value as PartnerOrganizationType)
                    }
                  >
                    {PARTNER_ORGANIZATION_TYPES.map((option) => (
                      <MenuItem key={option.value} value={option.value}>
                        {option.label}
                      </MenuItem>
                    ))}
                  </Select>
                  {errors.organizationType && (
                    <Typography variant="caption" color="error" sx={{ mt: 0.5, ml: 2 }}>
                      {errors.organizationType}
                    </Typography>
                  )}
                </FormControl>
              </>
            )}

            {/* First Name Field */}
            <TextField
              fullWidth
              label="First Name"
              value={formData.firstName}
              onChange={(e) => handleInputChange("firstName", e.target.value)}
              autoComplete="given-name"
              error={!!errors.firstName}
              helperText={errors.firstName}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <PersonOutline color="action" />
                  </InputAdornment>
                ),
              }}
            />

            {/* Last Name Field */}
            <TextField
              fullWidth
              label="Last Name"
              value={formData.lastName}
              onChange={(e) => handleInputChange("lastName", e.target.value)}
              autoComplete="family-name"
              error={!!errors.lastName}
              helperText={errors.lastName}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <PersonOutline color="action" />
                  </InputAdornment>
                ),
              }}
            />

            {/* Email Field */}
            <TextField
              fullWidth
              label="Email Address"
              type="email"
              value={formData.email}
              onChange={(e) => handleInputChange("email", e.target.value)}
              autoComplete="email"
              error={!!errors.email}
              helperText={errors.email}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <EmailOutlined color="action" />
                  </InputAdornment>
                ),
              }}
            />

            {/* Phone Field */}
            <TextField
              fullWidth
              label="Phone Number"
              value={formData.phone}
              onChange={(e) => handleInputChange("phone", e.target.value)}
              autoComplete="tel"
              error={!!errors.phone}
              helperText={errors.phone}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <PersonOutline color="action" />
                  </InputAdornment>
                ),
              }}
            />

            {/* Role Field */}
            {/* <FormControl fullWidth error={!!errors.role}>
              <InputLabel>Account Type</InputLabel>
              <Select
                value={formData.role}
                label="Account Type"
                onChange={(e) => handleInputChange("role", e.target.value)}
              >
                <MenuItem value="msme">MSME Company</MenuItem>
                <MenuItem value="view">View</MenuItem>
                <MenuItem value="admin">Administrator</MenuItem>
              </Select>
              {errors.role && (
                <Typography variant="caption" color="error" sx={{ mt: 0.5, ml: 2 }}>
                  {errors.role}
                </Typography>
              )}
            </FormControl> */}

            {/* Password Field */}
            <TextField
              fullWidth
              label="Password"
              type={showPassword ? "text" : "password"}
              value={formData.password}
              onChange={(e) => handleInputChange("password", e.target.value)}
              autoComplete="new-password"
              error={!!errors.password}
              helperText={errors.password || "Minimum 6 characters"}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <LockOutlined color="action" />
                  </InputAdornment>
                ),
                endAdornment: (
                  <InputAdornment position="end">
                    <IconButton
                      onClick={handleTogglePasswordVisibility}
                      edge="end"
                      aria-label="toggle password visibility"
                    >
                      {showPassword ? <VisibilityOff /> : <Visibility />}
                    </IconButton>
                  </InputAdornment>
                ),
              }}
            />

            {/* Confirm Password Field */}
            <TextField
              fullWidth
              label="Confirm Password"
              type={showConfirmPassword ? "text" : "password"}
              value={formData.confirmPassword}
              onChange={(e) => handleInputChange("confirmPassword", e.target.value)}
              autoComplete="new-password"
              error={!!errors.confirmPassword}
              helperText={errors.confirmPassword}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <LockOutlined color="action" />
                  </InputAdornment>
                ),
                endAdornment: (
                  <InputAdornment position="end">
                    <IconButton
                      onClick={handleToggleConfirmPasswordVisibility}
                      edge="end"
                      aria-label="toggle confirm password visibility"
                    >
                      {showConfirmPassword ? <VisibilityOff /> : <Visibility />}
                    </IconButton>
                  </InputAdornment>
                ),
              }}
            />

            {/* Terms and Conditions */}
            <Box>
              <FormControlLabel
                control={
                  <Checkbox
                    checked={formData.agreeToTerms}
                    onChange={(e) => handleInputChange("agreeToTerms", e.target.checked)}
                  />
                }
                label={
                  <Typography variant="body2">
                    I agree to the{" "}
                    <Link
                      component={RouterLink}
                      to="/terms-of-service"
                      sx={{ color: "primary.main" }}
                    >
                      Terms and Conditions
                    </Link>{" "}
                    and{" "}
                    <Link
                      component={RouterLink}
                      to="/privacy-policy"
                      sx={{ color: "primary.main" }}
                    >
                      Privacy Policy
                    </Link>
                  </Typography>
                }
              />
              {errors.agreeToTerms && (
                <Typography variant="caption" color="error" sx={{ ml: 2 }}>
                  {errors.agreeToTerms}
                </Typography>
              )}
            </Box>

            {/* Submit Button */}
            <Button
              type="submit"
              variant="contained"
              size="large"
              disabled={isRegistering}
              startIcon={
                isRegistering ? (
                  <CircularProgress size={20} color="inherit" />
                ) : (
                  submitButtonIcon
                )
              }
              sx={{
                py: 1.5,
                background: "linear-gradient(135deg, #4caf50 0%, #2e7d32 100%)",
                "&:hover": {
                  background:
                    "linear-gradient(135deg, #43a047 0%, #1b5e20 100%)",
                },
                "&:disabled": {
                  backgroundColor: theme.palette.action.disabledBackground,
                  color: theme.palette.action.disabled,
                },
              }}
            >
              {submitButtonLabel}
            </Button>

          </Stack>
        </form>

        {/* Divider */}
        <Divider sx={{ my: 4 }}>
          <Typography variant="body2" color="text.secondary">
            OR
          </Typography>
        </Divider>

        {/* Login Link */}
        <Box sx={{ textAlign: "center" }}>
          <Typography variant="body2" color="text.secondary" gutterBottom>
            Already have an account?
          </Typography>
          <Button
            component={RouterLink}
            to={accountType === "partner" ? "/login?type=partner" : "/login?type=msme"}
            variant="outlined"
            size="large"
            sx={{
              py: 1.5,
              borderColor: "success.main",
              color: "success.main",
              "&:hover": {
                borderColor: "success.dark",
                backgroundColor: alpha(theme.palette.success.main, isDark ? 0.14 : 0.06),
              },
            }}
          >
            Sign In
          </Button>
        </Box>

        {/* Footer Links */}
        <Stack
          direction="row"
          spacing={2}
          justifyContent="center"
          sx={{ mt: 3 }}
        >
          <Link
            component={RouterLink}
            to="/privacy-policy"
            variant="caption"
            color="text.secondary"
            sx={{
              textDecoration: "none",
              "&:hover": {
                textDecoration: "underline",
              },
            }}
          >
            Privacy Policy
          </Link>
          <Typography variant="caption" color="text.secondary">
            •
          </Typography>
          <Link
            component={RouterLink}
            to="/terms-of-service"
            variant="caption"
            color="text.secondary"
            sx={{
              textDecoration: "none",
              "&:hover": {
                textDecoration: "underline",
              },
            }}
          >
            Terms of Service
          </Link>
          {SUBSCRIPTION_PLANS_ENABLED ? (
            <>
              <Typography variant="caption" color="text.secondary">
                •
              </Typography>
              <Link
                component={RouterLink}
                to="/pricing"
                variant="caption"
                color="text.secondary"
                sx={{
                  textDecoration: "none",
                  "&:hover": {
                    textDecoration: "underline",
                  },
                }}
              >
                Pricing
              </Link>
            </>
          ) : null}
          <Typography variant="caption" color="text.secondary">
            •
          </Typography>
          <Link
            component={RouterLink}
            to="/help"
            variant="caption"
            color="text.secondary"
            sx={{
              textDecoration: "none",
              "&:hover": {
                textDecoration: "underline",
              },
            }}
          >
            Help
          </Link>
        </Stack>

        {partnerApiKeyFull ? (
          <PartnerOnboardingWizard
            open={partnerWizardOpen}
            apiKeyFull={partnerApiKeyFull}
            organizationName={formData.organizationName || "Partner organization"}
            onComplete={async (webhookUrl) => {
              if (webhookUrl) {
                try {
                  const token = localStorage.getItem("token");
                  if (token) {
                    await axios.patch(
                      buildApiUrl("/partner-account/webhook"),
                      { webhookUrl },
                      { headers: { Authorization: `Bearer ${token}` } }
                    );
                  }
                } catch {
                  /* optional */
                }
              }
            }}
          />
        ) : null}
      </Paper>
    </Box>
  );
};

export default UserRegister;