import React, { useMemo, useState } from 'react';
import {
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  Stack,
  Typography,
} from '@mui/material';
import { useNavigate } from 'react-router-dom';
import MitigationActionPicker from '../mitigation/MitigationActionPicker';
import { useMitigationActionSelection } from '../../hooks/useMitigationActionSelection';
import type { MitigationRecommendation } from '../../types/mitigation';

export interface DashboardRecommendationsCardProps {
  recommendations: MitigationRecommendation[];
  latestAssessmentId: string | null;
}

export const DashboardRecommendationsCard: React.FC<DashboardRecommendationsCardProps> = ({
  recommendations: initialRecommendations,
  latestAssessmentId,
}) => {
  const navigate = useNavigate();
  const [recommendations, setRecommendations] = useState(initialRecommendations);
  const [selectionError, setSelectionError] = useState<string | null>(null);

  React.useEffect(() => {
    setRecommendations(initialRecommendations);
  }, [initialRecommendations]);

  const visibleRecommendations = useMemo(
    () => recommendations.filter((rec) => !rec.isImplemented).slice(0, 3),
    [recommendations]
  );

  const { savingActionKey, handleToggleMitigationAction, canSelectActions } =
    useMitigationActionSelection({
      assessmentId: latestAssessmentId,
      recommendations,
      onRecommendationsChange: setRecommendations,
      onError: setSelectionError,
    });

  if (visibleRecommendations.length === 0) {
    return null;
  }

  return (
    <Card sx={{ mb: 3 }}>
      <CardContent>
        <Stack direction="row" alignItems="center" justifyContent="space-between" sx={{ mb: 1.5 }} flexWrap="wrap" gap={1}>
          <Box>
            <Typography variant="h6" sx={{ fontWeight: 700 }}>
              Reduction measures
            </Typography>
            <Typography variant="body2" color="text.secondary">
              Choose specific abatement actions tied to your latest assessment.
            </Typography>
          </Box>
          <Button size="small" onClick={() => navigate('/emissions-reduction-targets?tab=2')}>
            View all targets
          </Button>
        </Stack>

        {selectionError ? (
          <Typography variant="caption" color="error" display="block" sx={{ mb: 1 }}>
            {selectionError}
          </Typography>
        ) : null}

        <Stack spacing={2}>
          {visibleRecommendations.map((rec) => {
            const mitigationActions = rec.mitigationActions || [];
            const selectedActions = rec.selectedActions || [];
            const isDone = rec.isImplemented || rec.status === 'completed';

            return (
              <Box
                key={rec.id}
                sx={{
                  p: 1.5,
                  borderRadius: 2,
                  border: '1px solid',
                  borderColor: 'divider',
                }}
              >
                <Stack direction="row" alignItems="center" spacing={1} flexWrap="wrap" sx={{ mb: 0.5 }}>
                  <Typography variant="subtitle2">{rec.title}</Typography>
                  {rec.priority ? (
                    <Chip size="small" label={rec.priority} variant="outlined" />
                  ) : null}
                  {selectedActions.length > 0 ? (
                    <Chip
                      size="small"
                      color="success"
                      variant="outlined"
                      label={`${selectedActions.length} chosen`}
                    />
                  ) : null}
                </Stack>
                {rec.description ? (
                  <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                    {rec.description}
                  </Typography>
                ) : null}
                {mitigationActions.length > 0 && canSelectActions && !isDone ? (
                  <MitigationActionPicker
                    actions={mitigationActions}
                    selectedActions={selectedActions}
                    savingActionId={
                      savingActionKey?.startsWith(`${rec.id}::`)
                        ? savingActionKey.split('::')[1]
                        : null
                    }
                    onToggleAction={(action, selected) => {
                      void handleToggleMitigationAction(rec, action, selected);
                    }}
                  />
                ) : mitigationActions.length > 0 ? (
                  <Typography variant="caption" color="text.secondary">
                    Open Emissions Reduction Targets to choose measures for this recommendation.
                  </Typography>
                ) : null}
              </Box>
            );
          })}
        </Stack>
      </CardContent>
    </Card>
  );
};

export default DashboardRecommendationsCard;
