import React, { useCallback, useMemo, useState } from 'react';
import {
  Box,
  Button,
  Chip,
  Divider,
  FormControl,
  FormControlLabel,
  Grid,
  InputAdornment,
  InputLabel,
  LinearProgress,
  MenuItem,
  Paper,
  Select,
  Stack,
  Switch,
  TextField,
  ToggleButton,
  ToggleButtonGroup,
  Typography,
} from '@mui/material';
import {
  Calculate as CalculateIcon,
  PersonAdd as RegisterIcon,
  RestartAlt as ResetIcon,
} from '@mui/icons-material';
import { Link as RouterLink } from 'react-router-dom';
import { alpha, useTheme } from '@mui/material/styles';
import MarketingHeading from '../shared/MarketingHeading';

const { estimateSampleMsmeCarbon, COMPANY_TYPE_PRESETS } = require('../../shared/sampleMsmeCarbonEstimator.js');

const INDIAN_STATES: Array<{ value: string; label: string }> = [
  { value: 'maharashtra', label: 'Maharashtra' },
  { value: 'gujarat', label: 'Gujarat' },
  { value: 'karnataka', label: 'Karnataka' },
  { value: 'tamil nadu', label: 'Tamil Nadu' },
  { value: 'telangana', label: 'Telangana' },
  { value: 'andhra pradesh', label: 'Andhra Pradesh' },
  { value: 'delhi', label: 'Delhi NCR' },
  { value: 'haryana', label: 'Haryana' },
  { value: 'punjab', label: 'Punjab' },
  { value: 'uttar pradesh', label: 'Uttar Pradesh' },
  { value: 'rajasthan', label: 'Rajasthan' },
  { value: 'madhya pradesh', label: 'Madhya Pradesh' },
  { value: 'west bengal', label: 'West Bengal' },
  { value: 'kerala', label: 'Kerala' },
  { value: 'odisha', label: 'Odisha' },
  { value: 'bihar', label: 'Bihar' },
  { value: 'jharkhand', label: 'Jharkhand' },
  { value: 'chhattisgarh', label: 'Chhattisgarh' },
  { value: 'goa', label: 'Goa' },
  { value: 'assam', label: 'Assam' },
  { value: 'himachal pradesh', label: 'Himachal Pradesh' },
  { value: 'uttarakhand', label: 'Uttarakhand' },
];

type InputMode = 'spend' | 'metered';
type CompanyType = 'micro' | 'small' | 'medium';
type FuelType = 'diesel' | 'petrol' | 'lpg' | 'cng';

const COMPANY_TYPES: CompanyType[] = ['micro', 'small', 'medium'];

const SECTOR_OPTIONS = [
  { value: 'manufacturing', label: 'Manufacturing' },
  { value: 'textiles', label: 'Textiles' },
  { value: 'food_processing', label: 'Food processing' },
  { value: 'services', label: 'Services' },
  { value: 'logistics', label: 'Logistics' },
  { value: 'retail', label: 'Retail' },
  { value: 'electronics', label: 'Electronics' },
  { value: 'automotive', label: 'Automotive' },
];

const DEFAULT_STATE = 'maharashtra';
const DEFAULT_COMPANY: CompanyType = 'small';

const formatInr = (value: number) =>
  value.toLocaleString('en-IN', { maximumFractionDigits: 0 });

const formatKg = (value: number) =>
  value.toLocaleString('en-IN', { minimumFractionDigits: 1, maximumFractionDigits: 1 });

const SampleCarbonScoreCalculator: React.FC = () => {
  const theme = useTheme();
  const isDark = theme.palette.mode === 'dark';

  const [companyType, setCompanyType] = useState<CompanyType>(DEFAULT_COMPANY);
  const [sector, setSector] = useState('manufacturing');
  const [state, setState] = useState(DEFAULT_STATE);
  const [inputMode, setInputMode] = useState<InputMode>('spend');
  const [fuelType, setFuelType] = useState<FuelType>('diesel');
  const [electricitySpend, setElectricitySpend] = useState(
    String(COMPANY_TYPE_PRESETS.small.electricitySpendMonthly)
  );
  const [fuelSpend, setFuelSpend] = useState(String(COMPANY_TYPE_PRESETS.small.fuelSpendMonthly));
  const [electricityKwh, setElectricityKwh] = useState('10625');
  const [fuelQuantity, setFuelQuantity] = useState('355');
  const [renewableShare, setRenewableShare] = useState('10');
  const [annualTurnover, setAnnualTurnover] = useState(String(COMPANY_TYPE_PRESETS.small.annualTurnover));
  const [employeeCount, setEmployeeCount] = useState(String(COMPANY_TYPE_PRESETS.small.employeeCount));
  const [useTurnoverForIntensity, setUseTurnoverForIntensity] = useState(true);

  const applyCompanyPreset = useCallback((type: CompanyType) => {
    const preset = COMPANY_TYPE_PRESETS[type];
    setCompanyType(type);
    setElectricitySpend(String(preset.electricitySpendMonthly));
    setFuelSpend(String(preset.fuelSpendMonthly));
    setAnnualTurnover(String(preset.annualTurnover));
    setEmployeeCount(String(preset.employeeCount));
    const estKwh = Math.round(preset.electricitySpendMonthly / 8);
    setElectricityKwh(String(estKwh));
    setFuelQuantity(String(Math.round(preset.fuelSpendMonthly / 90)));
  }, []);

  const result = useMemo(
    () =>
      estimateSampleMsmeCarbon({
        inputMode,
        electricitySpendMonthly: Number(electricitySpend) || 0,
        fuelSpendMonthly: Number(fuelSpend) || 0,
        electricityKwhMonthly: Number(electricityKwh) || 0,
        fuelQuantityMonthly: Number(fuelQuantity) || 0,
        fuelType,
        sector,
        state,
        renewableSharePct: Number(renewableShare) || 0,
        companyType,
        annualTurnover: useTurnoverForIntensity ? Number(annualTurnover) || 0 : 0,
        employeeCount: Number(employeeCount) || 0,
      }),
    [
      inputMode,
      electricitySpend,
      fuelSpend,
      electricityKwh,
      fuelQuantity,
      fuelType,
      sector,
      state,
      renewableShare,
      companyType,
      annualTurnover,
      employeeCount,
      useTurnoverForIntensity,
    ]
  );

  const scoreColor = result.scoreTier as 'success' | 'warning' | 'error';

  return (
    <Paper
      elevation={0}
      sx={{
        p: { xs: 2.5, md: 3.5 },
        borderRadius: 3,
        border: `1px solid ${alpha(theme.palette.primary.main, isDark ? 0.35 : 0.22)}`,
        bgcolor: alpha(theme.palette.primary.main, isDark ? 0.08 : 0.04),
      }}
    >
      <Stack spacing={2.5}>
        <Box>
          <MarketingHeading level="h3" sx={{ mb: 1 }}>
            Estimate your MSME carbon score
          </MarketingHeading>
          <Typography variant="body2" color="text.secondary" sx={{ lineHeight: 1.7, maxWidth: 820 }}>
            Uses the same CEA grid factors, IPCC fuel factors, FERA supplements, and carbon score formula as
            registered assessments — based on your inputs, not verified bills. Register to replace estimates with
            document-backed scope 1–2 totals.
          </Typography>
        </Box>

        <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
          {COMPANY_TYPES.map((type) => (
            <Chip
              key={type}
              label={COMPANY_TYPE_PRESETS[type].label}
              color={companyType === type ? 'primary' : 'default'}
              variant={companyType === type ? 'filled' : 'outlined'}
              onClick={() => applyCompanyPreset(type)}
              sx={{ fontWeight: 600 }}
            />
          ))}
          <Chip
            icon={<ResetIcon fontSize="small" />}
            label="Reset to small MSME"
            variant="outlined"
            onClick={() => applyCompanyPreset('small')}
          />
        </Stack>

        <Grid container spacing={2}>
          <Grid item xs={12} sm={6} md={3}>
            <FormControl fullWidth>
              <InputLabel id="sample-sector-label">Business sector</InputLabel>
              <Select
                labelId="sample-sector-label"
                label="Business sector"
                value={sector}
                onChange={(event) => setSector(event.target.value)}
              >
                {SECTOR_OPTIONS.map((option) => (
                  <MenuItem key={option.value} value={option.value}>
                    {option.label}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <FormControl fullWidth>
              <InputLabel id="sample-state-label">Operating state</InputLabel>
              <Select
                labelId="sample-state-label"
                label="Operating state"
                value={state}
                onChange={(event) => setState(event.target.value)}
              >
                {INDIAN_STATES.map((option) => (
                  <MenuItem key={option.value} value={option.value}>
                    {option.label}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <TextField
              fullWidth
              label="Employees"
              type="number"
              value={employeeCount}
              onChange={(event) => setEmployeeCount(event.target.value)}
              inputProps={{ min: 1 }}
            />
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <TextField
              fullWidth
              label="Annual turnover"
              type="number"
              value={annualTurnover}
              onChange={(event) => setAnnualTurnover(event.target.value)}
              InputProps={{
                startAdornment: <InputAdornment position="start">₹</InputAdornment>,
              }}
              inputProps={{ min: 0 }}
              helperText={useTurnoverForIntensity ? 'Used for intensity scoring' : 'Optional context only'}
            />
          </Grid>
        </Grid>

        <Stack
          direction={{ xs: 'column', sm: 'row' }}
          spacing={2}
          alignItems={{ xs: 'stretch', sm: 'center' }}
          justifyContent="space-between"
        >
          <ToggleButtonGroup
            exclusive
            size="small"
            value={inputMode}
            onChange={(_event, value: InputMode | null) => {
              if (value) setInputMode(value);
            }}
          >
            <ToggleButton value="spend">Monthly spend (₹)</ToggleButton>
            <ToggleButton value="metered">Metered units (kWh / L)</ToggleButton>
          </ToggleButtonGroup>
          <FormControlLabel
            control={
              <Switch
                checked={useTurnoverForIntensity}
                onChange={(event) => setUseTurnoverForIntensity(event.target.checked)}
              />
            }
            label="Score intensity vs turnover"
          />
        </Stack>

        <Grid container spacing={2}>
          {inputMode === 'spend' ? (
            <>
              <Grid item xs={12} sm={6} md={3}>
                <TextField
                  fullWidth
                  label="Monthly electricity spend"
                  type="number"
                  value={electricitySpend}
                  onChange={(event) => setElectricitySpend(event.target.value)}
                  InputProps={{
                    startAdornment: <InputAdornment position="start">₹</InputAdornment>,
                  }}
                  inputProps={{ min: 0 }}
                />
              </Grid>
              <Grid item xs={12} sm={6} md={3}>
                <TextField
                  fullWidth
                  label="Monthly fuel spend"
                  type="number"
                  value={fuelSpend}
                  onChange={(event) => setFuelSpend(event.target.value)}
                  InputProps={{
                    startAdornment: <InputAdornment position="start">₹</InputAdornment>,
                  }}
                  inputProps={{ min: 0 }}
                />
              </Grid>
            </>
          ) : (
            <>
              <Grid item xs={12} sm={6} md={3}>
                <TextField
                  fullWidth
                  label="Monthly electricity (kWh)"
                  type="number"
                  value={electricityKwh}
                  onChange={(event) => setElectricityKwh(event.target.value)}
                  inputProps={{ min: 0 }}
                />
              </Grid>
              <Grid item xs={12} sm={6} md={3}>
                <TextField
                  fullWidth
                  label="Monthly fuel quantity"
                  type="number"
                  value={fuelQuantity}
                  onChange={(event) => setFuelQuantity(event.target.value)}
                  InputProps={{
                    endAdornment: <InputAdornment position="end">L or kg</InputAdornment>,
                  }}
                  inputProps={{ min: 0 }}
                />
              </Grid>
            </>
          )}
          <Grid item xs={12} sm={6} md={3}>
            <FormControl fullWidth>
              <InputLabel id="sample-fuel-label">Primary fuel</InputLabel>
              <Select
                labelId="sample-fuel-label"
                label="Primary fuel"
                value={fuelType}
                onChange={(event) => setFuelType(event.target.value as FuelType)}
              >
                <MenuItem value="diesel">Diesel</MenuItem>
                <MenuItem value="petrol">Petrol</MenuItem>
                <MenuItem value="lpg">LPG</MenuItem>
                <MenuItem value="cng">CNG</MenuItem>
              </Select>
            </FormControl>
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <TextField
              fullWidth
              label="Renewable electricity share"
              type="number"
              value={renewableShare}
              onChange={(event) => setRenewableShare(event.target.value)}
              InputProps={{
                endAdornment: <InputAdornment position="end">%</InputAdornment>,
              }}
              inputProps={{ min: 0, max: 100 }}
            />
          </Grid>
        </Grid>

        <Grid container spacing={2} alignItems="stretch">
          <Grid item xs={12} md={5}>
            <Paper
              variant="outlined"
              sx={{
                height: '100%',
                p: 2.5,
                borderRadius: 2.5,
                display: 'flex',
                flexDirection: 'column',
                justifyContent: 'center',
                alignItems: 'center',
                textAlign: 'center',
              }}
            >
              <Typography variant="overline" color="text.secondary" sx={{ fontWeight: 700 }}>
                Estimated carbon score
              </Typography>
              <Typography
                variant="h2"
                sx={{
                  fontWeight: 800,
                  lineHeight: 1,
                  my: 1,
                  color: `${scoreColor}.main`,
                }}
              >
                {result.carbonScore}
              </Typography>
              <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 1 }}>
                {result.scoreLabel}
              </Typography>
              <LinearProgress
                variant="determinate"
                value={result.carbonScore}
                color={scoreColor}
                sx={{ width: '100%', height: 8, borderRadius: 1, mb: 1.5 }}
              />
              <Typography variant="caption" color="text.secondary">
                Illustrative — same scoring engine as registered MSME accounts.
              </Typography>
            </Paper>
          </Grid>
          <Grid item xs={12} md={7}>
            <Stack spacing={1.25} sx={{ height: '100%', justifyContent: 'center' }}>
              <Typography variant="body2" color="text.secondary">
                <strong>Monthly emissions (incl. FERA):</strong> {formatKg(result.totalEmissionsKgMonthly)} kg CO₂e
                {' · '}
                <strong>Annual:</strong> {formatKg(result.totalEmissionsKgAnnual)} kg CO₂e
              </Typography>
              <Typography variant="body2" color="text.secondary">
                <strong>Scope 1 (fuel):</strong> {formatKg(result.scope1Kg)} kg
                {' · '}
                <strong>Scope 2 (electricity):</strong> {formatKg(result.scope2Kg)} kg
                {' · '}
                <strong>Scope 3 FERA:</strong> {formatKg(result.feraScope3Kg)} kg
              </Typography>
              <Typography variant="body2" color="text.secondary">
                <strong>Grid factor:</strong> {result.derived.gridFactor.toFixed(2)} kg/kWh ({state})
                {' · '}
                <strong>Derived:</strong> {Math.round(result.derived.gridKwh).toLocaleString('en-IN')} kWh grid
                {result.derived.renewableKwh > 0
                  ? `, ${Math.round(result.derived.renewableKwh).toLocaleString('en-IN')} kWh renewable`
                  : ''}
                {result.derived.fuelQuantity > 0
                  ? ` · ${Math.round(result.derived.fuelQuantity).toLocaleString('en-IN')} L ${result.derived.fuelType}`
                  : ''}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                <strong>Intensity:</strong> {result.intensityPer1000Inr.toFixed(2)} kg CO₂e per ₹1,000{' '}
                {useTurnoverForIntensity ? 'turnover' : 'energy spend'}
                {result.perEmployeeKg != null ? (
                  <>
                    {' · '}
                    <strong>Per employee:</strong> {formatKg(result.perEmployeeKg)} kg CO₂e / month
                  </>
                ) : null}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                <strong>Sample monthly energy spend:</strong> ₹{formatInr(result.monthlySpend)}
              </Typography>
              <Divider sx={{ my: 0.5 }} />
              <Typography variant="body2" color="text.secondary">
                After registration, upload utility bills and connect Tally/Zoho to replace spend proxies with
                OCR-backed kWh, fuel quantities, sector benchmarks, and buyer-ready BRSR / ISO exports.
              </Typography>
              <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1.25} sx={{ pt: 0.5 }}>
                <Button
                  component={RouterLink}
                  to="/register?type=msme"
                  variant="contained"
                  startIcon={<RegisterIcon />}
                  sx={{ textTransform: 'none', fontWeight: 700 }}
                >
                  Register your MSME
                </Button>
                <Button
                  component={RouterLink}
                  to="/login"
                  variant="outlined"
                  startIcon={<CalculateIcon />}
                  sx={{ textTransform: 'none', fontWeight: 600 }}
                >
                  Sign in for full assessment
                </Button>
              </Stack>
            </Stack>
          </Grid>
        </Grid>
      </Stack>
    </Paper>
  );
};

export default SampleCarbonScoreCalculator;
