/**
 * Pre-login MSME carbon score estimator — uses the same emission factors,
 * unit prices, regional grid factors, FERA supplements, and carbon score
 * formula as the registered assessment pipeline (illustrative, not verified).
 */
const carbonScoreCalculation = require('./carbonScoreCalculation');
const { getActivityEmissionFactors, getRegionalGridFactors } = require('./emissionFactorRegistry');
const CARBON_SHARED = require('./carbonEmissionDefaults.json');

const UNIT_PRICES = Object.freeze({
  electricity: { grid: 8, renewable: 5, mixed: 7 },
  fuel: { diesel: 90, petrol: 103, lpg: 75, cng: 76, coal: 15, natural_gas: 55 },
});

const SECTOR_TO_DOMAIN = Object.freeze({
  manufacturing: 'manufacturing',
  textiles: 'textiles',
  food_processing: 'food_processing',
  services: 'services',
  logistics: 'logistics',
  retail: 'retail',
  electronics: 'electronics',
  automotive: 'automotive',
  food_products_industry: 'food_processing',
});

const COMPANY_TYPE_PRESETS = Object.freeze({
  micro: {
    label: 'Micro enterprise',
    electricitySpendMonthly: 25000,
    fuelSpendMonthly: 8000,
    employeeCount: 8,
    annualTurnover: 6000000,
  },
  small: {
    label: 'Small enterprise',
    electricitySpendMonthly: 85000,
    fuelSpendMonthly: 32000,
    employeeCount: 45,
    annualTurnover: 50000000,
  },
  medium: {
    label: 'Medium enterprise',
    electricitySpendMonthly: 350000,
    fuelSpendMonthly: 120000,
    employeeCount: 180,
    annualTurnover: 350000000,
  },
});

const INDIAN_STATE_OPTIONS = Object.freeze([
  { value: 'maharashtra', label: 'Maharashtra' },
  { value: 'gujarat', label: 'Gujarat' },
  { value: 'karnataka', label: 'Karnataka' },
  { value: 'tamil nadu', label: 'Tamil Nadu' },
  { value: 'telangana', label: 'Telangana' },
  { value: 'andhra pradesh', label: 'Andhra Pradesh' },
  { value: 'delhi', label: 'Delhi NCR' },
  { value: 'haryana', label: 'Haryana' },
  { value: 'punjab', label: 'Punjab' },
  { value: 'uttar pradesh', label: 'Uttar Pradesh' },
  { value: 'rajasthan', label: 'Rajasthan' },
  { value: 'madhya pradesh', label: 'Madhya Pradesh' },
  { value: 'west bengal', label: 'West Bengal' },
  { value: 'kerala', label: 'Kerala' },
  { value: 'odisha', label: 'Odisha' },
  { value: 'bihar', label: 'Bihar' },
  { value: 'jharkhand', label: 'Jharkhand' },
  { value: 'chhattisgarh', label: 'Chhattisgarh' },
  { value: 'goa', label: 'Goa' },
  { value: 'assam', label: 'Assam' },
  { value: 'himachal pradesh', label: 'Himachal Pradesh' },
  { value: 'uttarakhand', label: 'Uttarakhand' },
]);

const clamp = (value, min, max) => Math.min(max, Math.max(min, value));

const normalizeState = (state) =>
  String(state || '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' ');

const resolveGridFactor = (state) => {
  const regional = getRegionalGridFactors();
  const normalized = normalizeState(state);
  if (normalized && Number.isFinite(regional[normalized])) {
    return regional[normalized];
  }
  const activityFactors = getActivityEmissionFactors();
  return regional.default ?? activityFactors?.electricity?.grid ?? 0.82;
};

const resolveFuelFactor = (fuelType) => {
  const activityFactors = getActivityEmissionFactors();
  return activityFactors?.fuel?.[fuelType] ?? activityFactors?.fuel?.diesel ?? 2.68;
};

const resolveFuelUnitPrice = (fuelType) => UNIT_PRICES.fuel[fuelType] ?? UNIT_PRICES.fuel.diesel;

const computeFeraSupplement = (directKg, energyType) => {
  const config = CARBON_SHARED.feraModeling || {};
  if (config.enabledInComplianceMode === false || directKg <= 0) {
    return 0;
  }
  if (energyType === 'renewable') {
    return directKg * (config.renewableElectricityUpstreamShare ?? 0.02);
  }
  if (energyType === 'fuel') {
    return directKg * (config.fuelUpstreamShare ?? 0.18);
  }
  return directKg * (config.electricityUpstreamShare ?? 0.08);
};

const scoreLabel = (score) => {
  if (score >= 80) return 'Excellent';
  if (score >= 60) return 'Good';
  if (score >= 40) return 'Average';
  return 'Needs improvement';
};

const scoreTier = (score) => {
  if (score >= 60) return 'success';
  if (score >= 40) return 'warning';
  return 'error';
};

/**
 * @param {object} input
 * @param {'spend'|'metered'} [input.inputMode]
 * @param {number} [input.electricitySpendMonthly]
 * @param {number} [input.fuelSpendMonthly]
 * @param {number} [input.electricityKwhMonthly]
 * @param {number} [input.fuelQuantityMonthly]
 * @param {'diesel'|'petrol'|'lpg'|'cng'} [input.fuelType]
 * @param {string} [input.sector]
 * @param {string} [input.state]
 * @param {number} [input.renewableSharePct]
 * @param {'micro'|'small'|'medium'} [input.companyType]
 * @param {number} [input.annualTurnover]
 * @param {number} [input.employeeCount]
 */
const estimateSampleMsmeCarbon = (input = {}) => {
  const inputMode = input.inputMode === 'metered' ? 'metered' : 'spend';
  const fuelType = input.fuelType || 'diesel';
  const sector = input.sector || 'manufacturing';
  const businessDomain = SECTOR_TO_DOMAIN[sector] || sector;
  const renewableSharePct = clamp(Number(input.renewableSharePct) || 0, 0, 100);
  const renewableShare = renewableSharePct / 100;
  const gridFactor = resolveGridFactor(input.state);
  const fuelFactor = resolveFuelFactor(fuelType);
  const activityFactors = getActivityEmissionFactors();
  const renewableFactor = activityFactors?.electricity?.renewable ?? 0.1;

  let gridKwh = 0;
  let renewableKwh = 0;
  let fuelQuantity = 0;
  let electricitySpend = Math.max(0, Number(input.electricitySpendMonthly) || 0);
  let fuelSpend = Math.max(0, Number(input.fuelSpendMonthly) || 0);

  if (inputMode === 'metered') {
    const totalKwh = Math.max(0, Number(input.electricityKwhMonthly) || 0);
    renewableKwh = totalKwh * renewableShare;
    gridKwh = totalKwh - renewableKwh;
    fuelQuantity = Math.max(0, Number(input.fuelQuantityMonthly) || 0);
    electricitySpend = gridKwh * UNIT_PRICES.electricity.grid + renewableKwh * UNIT_PRICES.electricity.renewable;
    fuelSpend = fuelQuantity * resolveFuelUnitPrice(fuelType);
  } else {
    const renewableSpend = electricitySpend * renewableShare;
    const gridSpend = electricitySpend - renewableSpend;
    gridKwh = gridSpend / UNIT_PRICES.electricity.grid;
    renewableKwh = renewableSpend / UNIT_PRICES.electricity.renewable;
    fuelQuantity = fuelSpend / resolveFuelUnitPrice(fuelType);
  }

  const gridEmissions = gridKwh * gridFactor;
  const renewableEmissions = renewableKwh * renewableFactor;
  const electricityEmissions = gridEmissions + renewableEmissions;
  const fuelEmissions = fuelQuantity * fuelFactor;

  const scope1Kg = fuelEmissions;
  const scope2Kg = electricityEmissions;
  const feraScope3Kg =
    computeFeraSupplement(fuelEmissions, 'fuel') +
    computeFeraSupplement(gridEmissions, 'electricity') +
    computeFeraSupplement(renewableEmissions, 'renewable');

  const totalEmissionsKgMonthly = scope1Kg + scope2Kg + feraScope3Kg;
  const totalEmissionsKgAnnual = totalEmissionsKgMonthly * 12;
  const monthlySpend = electricitySpend + fuelSpend;
  const annualSpendFromBills = monthlySpend * 12;
  const annualTurnover = Math.max(0, Number(input.annualTurnover) || 0);
  const spendBasis = annualTurnover > 0 ? annualTurnover : annualSpendFromBills || 100000;

  const assessment = {
    totalCO2Emissions: totalEmissionsKgAnnual,
    totalSpend: spendBasis,
    totalAmount: spendBasis,
    breakdown: {
      energy: {
        electricity: gridEmissions,
        fuel: fuelEmissions,
        renewable: renewableEmissions,
        total: electricityEmissions + fuelEmissions,
      },
    },
  };

  const msmeData = {
    businessDomain,
    industry: sector,
    annualTurnover: annualTurnover > 0 ? annualTurnover : undefined,
    manufacturingProfile: {
      renewableEnergyShare: renewableSharePct,
      employeeCount: Math.max(0, Number(input.employeeCount) || 0) || undefined,
    },
  };

  const carbonScore = carbonScoreCalculation.calculateCarbonScore(assessment, msmeData);
  const intensityPer1000Inr = spendBasis > 0 ? (totalEmissionsKgAnnual / spendBasis) * 1000 : 0;
  const perEmployeeKg =
    Number(input.employeeCount) > 0 ? totalEmissionsKgMonthly / Number(input.employeeCount) : null;

  return {
    carbonScore,
    scoreLabel: scoreLabel(carbonScore),
    scoreTier: scoreTier(carbonScore),
    totalEmissionsKgMonthly,
    totalEmissionsKgAnnual,
    scope1Kg,
    scope2Kg,
    feraScope3Kg,
    intensityPer1000Inr,
    perEmployeeKg,
    monthlySpend,
    spendBasis,
    inputMode,
    derived: {
      gridKwh,
      renewableKwh,
      fuelQuantity,
      fuelType,
      gridFactor,
      fuelFactor,
      renewableFactor,
    },
    breakdown: assessment.breakdown,
  };
};

module.exports = {
  UNIT_PRICES,
  SECTOR_TO_DOMAIN,
  COMPANY_TYPE_PRESETS,
  INDIAN_STATE_OPTIONS,
  estimateSampleMsmeCarbon,
  scoreLabel,
  scoreTier,
};
