import React, { useState } from 'react';
import {
  Accordion,
  AccordionDetails,
  AccordionSummary,
  Box,
  Typography,
} from '@mui/material';
import { ExpandMore as ExpandMoreIcon } from '@mui/icons-material';
import useAppTranslation from '../../hooks/useAppTranslation';

export interface DashboardSetupFocusSectionProps {
  children: React.ReactNode;
  defaultExpanded?: boolean;
}

/**
 * Collapses advanced dashboard panels while MSME setup is still in progress,
 * so first-time users see a shorter, action-oriented home screen.
 */
export const DashboardSetupFocusSection: React.FC<DashboardSetupFocusSectionProps> = ({
  children,
  defaultExpanded = false,
}) => {
  const [expanded, setExpanded] = useState(defaultExpanded);
  const { t } = useAppTranslation();

  return (
    <Accordion
      expanded={expanded}
      onChange={(_, isExpanded) => setExpanded(isExpanded)}
      variant="outlined"
      sx={{ mb: 3 }}
    >
      <AccordionSummary expandIcon={<ExpandMoreIcon />} aria-controls="dashboard-advanced-content">
        <Box>
          <Typography variant="subtitle1" sx={{ fontWeight: 700 }}>
            {t('dashboard.setupFocusTitle')}
          </Typography>
          <Typography variant="body2" color="text.secondary">
            {t('dashboard.setupFocusSubtitle')}
          </Typography>
        </Box>
      </AccordionSummary>
      <AccordionDetails sx={{ pt: 0 }}>{children}</AccordionDetails>
    </Accordion>
  );
};

export default DashboardSetupFocusSection;
