/** True when blocked reason text suggests missing uploads rather than readiness scoring. */
export const isMsmeDataGapReason = (text = ''): boolean => {
  const normalized = String(text || '').toLowerCase();
  return /upload|bill|document|ocr|utility|electricity|fuel|meter|kwh|litre|liter|invoice|receipt/.test(normalized);
};

export const msmeExportPrimaryAction = (
  primaryGap: { label: string; link: string } | null
): { label: string; type: 'link' | 'orchestrate'; link?: string } => {
  if (!primaryGap) {
    return { label: MSME_SIMPLIFIED_ACTION_LABELS.checkReadinessFirst, type: 'orchestrate' };
  }
  if (isMsmeDataGapReason(primaryGap.label)) {
    const link = /document|upload|bill/.test(primaryGap.link) ? primaryGap.link : '/document-upload';
    return { label: MSME_SIMPLIFIED_ACTION_LABELS.uploadBills, type: 'link', link };
  }
  return { label: MSME_SIMPLIFIED_ACTION_LABELS.checkReadinessFirst, type: 'orchestrate' };
};

/** Hide technical panels on MSME reporting overview. */
export const MSME_HIDE_REPORTING_PANELS = {
  remediationTrackDetails: true,
  agentAdvisoryDetails: true,
  blendedScoreBreakdown: true,
  sectorLensAlert: true,
} as const;

/** Hide technical panels on MSME reporting overview unless expert mode is on. */
export const shouldHideReportingPanel = (
  panel: keyof typeof MSME_HIDE_REPORTING_PANELS,
  isMsmeSimplified: boolean,
  expertMode: boolean
): boolean => isMsmeSimplified && MSME_HIDE_REPORTING_PANELS[panel] && !expertMode;

export const msmeSimplifiedActionLabel = (action: string, dataFeedSatisfied?: boolean): string => {
  if (!dataFeedSatisfied) {
    return action;
  }
  if (/upload/i.test(action)) {
    return action.replace(/upload/gi, 'Review');
  }
  return action;
};
