import React, { useEffect, useState } from 'react';
import { Navigate } from 'react-router-dom';
import { Box, CircularProgress } from '@mui/material';
import ApiService from '../../services/api';
import { persistAdminPortalSession } from '../../utils/adminPortalSession';

interface SupportRouteProps {
  children: React.ReactNode;
}

const SupportRoute: React.FC<SupportRouteProps> = ({ children }) => {
  const [checking, setChecking] = useState(true);
  const [isSupport, setIsSupport] = useState(false);

  useEffect(() => {
    checkSupportStatus();
  }, []);

  const checkSupportStatus = async () => {
    const token = localStorage.getItem('token');

    if (!token) {
      setIsSupport(false);
      setChecking(false);
      return;
    }

    try {
      const response = await ApiService.request('/auth/me');
      const user = response?.data?.user;
      const role = user?.role;
      const hasSupportRole = role === 'support';

      if (hasSupportRole && user) {
        persistAdminPortalSession(user, token);
      }

      setIsSupport(hasSupportRole);

      if (!hasSupportRole) {
        localStorage.removeItem('token');
        localStorage.removeItem('adminUser');
      }
    } catch (error) {
      console.error('Support session validation failed:', error);
      localStorage.removeItem('token');
      localStorage.removeItem('adminUser');
      setIsSupport(false);
    } finally {
      setChecking(false);
    }
  };

  if (checking) {
    return (
      <Box
        sx={{
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          minHeight: '100vh',
        }}
      >
        <CircularProgress />
      </Box>
    );
  }

  if (!isSupport) {
    return <Navigate to="/login" replace />;
  }

  return <>{children}</>;
};

export default SupportRoute;
