/**
 * CPCB emission factor library loader — merges CPCB categories into registry lookups.
 */
const CPCB_DOC = require('./cpcbEmissionFactors.json');

const flattenCpcbFactors = () => {
  const flat = {};
  Object.values(CPCB_DOC.categories || {}).forEach((category) => {
    Object.entries(category.factors || {}).forEach(([key, row]) => {
      flat[key] = { ...row, cpcbCategoryLabel: category.label };
    });
  });
  return flat;
};

const CPCB_FACTORS = Object.freeze(flattenCpcbFactors());

const listCpcbFactorIds = () => Object.keys(CPCB_FACTORS);

const getCpcbFactor = (id) => CPCB_FACTORS[id] || null;

const resolveCpcbFactorsForInvoiceCategory = (invoiceCategory) => {
  const mapped = CPCB_DOC.invoiceCategoryMapping?.[invoiceCategory];
  if (!Array.isArray(mapped)) return [];
  return mapped.map((id) => CPCB_FACTORS[id] || getCpcbFactor(id)).filter(Boolean);
};

const getCpcbRegistryMetadata = () => ({
  registryVersion: CPCB_DOC.registryVersion,
  authority: CPCB_DOC.authority,
  methodologyNote: CPCB_DOC.methodologyNote,
  factorCount: listCpcbFactorIds().length,
  categories: Object.keys(CPCB_DOC.categories || {})
});

module.exports = {
  CPCB_FACTORS,
  listCpcbFactorIds,
  getCpcbFactor,
  resolveCpcbFactorsForInvoiceCategory,
  getCpcbRegistryMetadata
};
